INSERT INTO feature VALUES('rap-toolset','editor','The Reactive Agent Protocol toolset','engine-hub','implemented','uncommon','mainstream editors','`gandr serve` serves the hub''s tools to an agent runtime over HTTP on the loopback interface, on a free port or the one `--port` names, unless it is told `--no-toolset`, and writes the manifest''s URL to a file beside the hub''s socket: the manifest at `/.well-known/rap-toolset`, read from the table of operations the Model Context Protocol face lists, and an invoke endpoint that acknowledges each call once its row is stored and answers it later by a callback with a `tool_result`; a refusal, an unknown operation and a call a crash lost are answered with an `Error:` text, and the caller''s own bearer rides back on the callback. A second hub of the workspace stops while the file names a toolset that listens.','surface-agentic surface-lsp surface-driver','crates/surface-agentic/src/rap.rs crates/surface-driver/tests/cli.rs',NULL,'#6339 #6343');
